# This file is automatically @generated by Cargo.
# It is not intended for manual editing.
[[package]]
name = "serde"
version = "1.0.160"
source = "registry+https://github.com/rust-lang/crates.io-index"
checksum = "bb2f3770ded5b0f5929b73094f85fcba14c3abc"

[[package]]
name = "serde_json"
version = "1.0.96"
source = "registry+https://github.com/rust-lang/crates.io-index"
checksum = "057d394a50403bcac12672b2b18fb387ab"
dependencies = [
 "serde",
]

[[package]]
name = "myapp"
version = "0.1.0"
dependencies = [
 "serde",
 "serde_json",
]
"""

CARGO_LOCK_V3 = """\
# This file is automatically @generated by Cargo.
# It is not intended for manual editing.
version = 3

[[package]]
name = "anyhow"
